<script setup>
import { computed, ref } from 'vue'; import { useRouter } from 'vue-router'; import { AlertCircle, ArrowRight, CheckCircle, Clock, FileText, MinusCircle, TrendingDown, TrendingUp } from 'lucide-vue-next'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import { currentMonthKey, formatCurrency, formatDate } from '@/utils/formatters'; import { useInvoiceStore } from '@/stores/invoice'; import { usePaymentStore } from '@/stores/payment'; import { useFinanceStore } from '@/stores/finance';
const router=useRouter(),invoices=useInvoiceStore(),payments=usePaymentStore(),finance=useFinanceStore(),period=ref('Bulan Ini'),activeChart=ref(null);const periodLabel=computed(()=>({ 'Bulan Ini':'bulan ini','3 Bulan Terakhir':'3 bulan terakhir','Tahun Ini':'tahun ini'})[period.value]);const months=computed(()=>{const now=new Date(`${currentMonthKey()}-01T00:00:00`),count=period.value==='Bulan Ini'?1:period.value==='3 Bulan Terakhir'?3:12;return Array.from({length:count},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-count+i+1,1);return{key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,label:d.toLocaleDateString('id-ID',{month:'short'})}})});const inside=date=>months.value.some(m=>date?.slice(0,7)===m.key);const chart=computed(()=>months.value.map(m=>({label:m.label,income:finance.allIncomes.filter(x=>x.date.slice(0,7)===m.key).reduce((s,x)=>s+x.amount,0),expense:finance.expenses.filter(x=>x.date.slice(0,7)===m.key).reduce((s,x)=>s+x.amount,0)})));const max=computed(()=>Math.max(1,...chart.value.flatMap(x=>[x.income,x.expense])));const groupWidth=computed(()=>578/Math.max(1,chart.value.length));const barWidth=computed(()=>Math.max(5,Math.min(14,(groupWidth.value-8)/2)));const x=i=>60+i*groupWidth.value;const h=v=>Math.max(0,Math.round(v/max.value*134));const y=v=>142-h(v);const metrics=computed(()=>({invoice:invoices.invoices.filter(x=>x.status!=='cancelled'&&inside(x.date)).length,outstanding:invoices.invoices.filter(x=>x.status==='published'&&inside(x.date)).reduce((s,x)=>s+payments.paymentSummaryByInvoice(x).remaining,0),income:finance.allIncomes.filter(x=>inside(x.date)).reduce((s,x)=>s+x.amount,0),expense:finance.expenses.filter(x=>inside(x.date)).reduce((s,x)=>s+x.amount,0)}));const cards=computed(()=>[{label:'Total Invoice',value:metrics.value.invoice,icon:FileText,route:'invoice'},{label:'Sisa Tagihan',value:formatCurrency(metrics.value.outstanding),icon:AlertCircle,route:'billing'},{label:'Total Pemasukan',value:formatCurrency(metrics.value.income),icon:TrendingUp,route:'pemasukan'},{label:'Total Pengeluaran',value:formatCurrency(metrics.value.expense),icon:TrendingDown,route:'pengeluaran'}]);const statuses=computed(()=>[{key:'belum_dibayar',label:'Belum Dibayar',icon:MinusCircle},{key:'dibayar_sebagian',label:'Dibayar Sebagian',icon:Clock},{key:'lunas',label:'Lunas',icon:CheckCircle},{key:'jatuh_tempo',label:'Jatuh Tempo',icon:AlertCircle}].map(s=>({...s,count:invoices.invoices.filter(x=>x.status==='published'&&inside(x.date)&&payments.paymentSummaryByInvoice(x).status===s.key).length})));const recent=computed(()=>invoices.invoices.filter(x=>inside(x.date)).map(x=>({...x,total:payments.paymentSummaryByInvoice(x).total,status:payments.paymentSummaryByInvoice(x).status})).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5));const badge=s=>({belum_dibayar:['Belum Dibayar','neutral'],dibayar_sebagian:['Dibayar Sebagian','warning'],lunas:['Lunas','success'],jatuh_tempo:['Jatuh Tempo','danger']}[s]);
</script>
<template><div class="space-y-4 p-6"><header class="flex items-center justify-between"><div><h1 class="text-[18px] font-semibold text-[#172033]">Dashboard</h1><p class="text-[13px] text-[#9CA3AF]">Ringkasan keuangan dan aktivitas {{periodLabel}}</p></div><select v-model="period" class="h-8 rounded-md border border-[#E2E6EC] px-3 text-[13px]"><option>Bulan Ini</option><option>3 Bulan Terakhir</option><option>Tahun Ini</option></select></header><div class="grid grid-cols-1 gap-3.5 sm:grid-cols-2 xl:grid-cols-4"><button v-for="card in cards" :key="card.label" class="rounded-lg border border-[#E2E6EC] bg-white p-4 text-left" @click="router.push({name:card.route})"><component :is="card.icon" :size="15" class="mb-3 text-[#173B6C]"/><p class="text-[11px] uppercase text-[#9CA3AF]">{{card.label}}</p><p class="text-xl font-bold">{{card.value}}</p><p class="mt-1 text-[11px] text-[#B0BAC7]">{{periodLabel}}</p></button></div><div class="grid grid-cols-1 gap-3.5 xl:grid-cols-3"><BaseCard><h2 class="mb-3 text-sm font-semibold">Status Invoice</h2><div v-for="s in statuses" :key="s.key" class="flex justify-between py-2 text-sm"><span class="flex gap-2"><component :is="s.icon" :size="14"/>{{s.label}}</span><b>{{s.count}}</b></div></BaseCard><BaseCard class="xl:col-span-2"><h2 class="mb-3 text-sm font-semibold">Pemasukan vs Pengeluaran</h2><div class="relative h-44 overflow-hidden"><svg class="h-full w-full" viewBox="0 0 640 176" preserveAspectRatio="none"><g v-for="tick in [max,max*.75,max*.5,max*.25,0]" :key="tick"><line x1="60" x2="638" :y1="y(tick)" :y2="y(tick)" stroke="#F3F4F6"/></g><g v-for="(m,i) in chart" :key="m.label" @mouseenter="activeChart=m" @mouseleave="activeChart=null"><rect :x="x(i)" y="0" :width="groupWidth" height="154" fill="transparent"/><rect :x="x(i)+groupWidth/2-barWidth-2" :y="y(m.income)" :width="barWidth" :height="h(m.income)" rx="2" fill="#173B6C"/><rect :x="x(i)+groupWidth/2+2" :y="y(m.expense)" :width="barWidth" :height="h(m.expense)" rx="2" fill="#EF4444"/><text :x="x(i)+groupWidth/2" y="171" text-anchor="middle" fill="#B0BAC7" font-size="10">{{m.label}}</text></g></svg><div v-if="activeChart" class="absolute left-16 top-1 rounded bg-white px-2 text-xs shadow">{{activeChart.label}} · {{formatCurrency(activeChart.income)}} / {{formatCurrency(activeChart.expense)}}</div></div></BaseCard></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><div class="flex justify-between border-b p-4"><h2 class="text-sm font-semibold">Invoice Terbaru</h2><button class="text-xs text-[#315DA8]" @click="router.push({name:'invoice'})">Lihat Semua <ArrowRight :size="12" class="inline"/></button></div><table class="w-full min-w-[640px]"><thead><tr class="border-b"><th v-for="h in ['Nomor Invoice','Klien','Jatuh Tempo','Total','Status']" :key="h" class="px-4 py-3 text-left text-xs text-[#667085]">{{h}}</th></tr></thead><tbody><tr v-for="row in recent" :key="row.id" class="cursor-pointer border-b" @click="router.push({name:'invoice-detail',params:{id:row.id}})"><td class="px-4 py-3 text-sm">{{row.number}}</td><td class="px-4 py-3 text-sm">{{row.client}}</td><td class="px-4 py-3 text-sm">{{formatDate(row.dueDate)}}</td><td class="px-4 py-3 text-right text-sm">{{formatCurrency(row.total)}}</td><td class="px-4 py-3"><BaseBadge :variant="badge(row.status)[1]">{{badge(row.status)[0]}}</BaseBadge></td></tr></tbody></table></section></div></template>
